    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property() public {
        // Call XBornID() which sets totalDistributed, then totalRemaining becomes 300000000e18
        c.XBornID();
        // After XBornID(), value should still be 1000e18 because totalRemaining > value
        // In reference, value stays 1000e18 (non-zero). In mutant, value becomes 0.
        assertTrue(c.value() > 0);
    }
}

