// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property() public {
        // Call XBornID() to set the distribution state
        c.XBornID();

        // Capture totalRemaining after XBornID()
        uint256 totalRemaining = c.totalRemaining();

        // Ensure value > totalRemaining so the if-branch is taken
        vm.assume(c.value() > totalRemaining);

        uint256 valueBefore = c.value();

        // Call getTokens() – in the reference, value is set to totalRemaining; in the bug, value is set to 0
        c.getTokens();

        uint256 valueAfter = c.value();

        // The general rule: after getTokens() when value > totalRemaining, value should NOT become 0
        // In the reference, value becomes totalRemaining (which is > 0 if totalRemaining > 0) or unchanged if totalRemaining is 0
        // In the bug, value becomes 0, which violates the invariant that value > 0 or at least not zero after distribution
        // Since totalRemaining may be 0, we assert that valueAfter is NOT 0 when valueBefore > 0
        // But the strongest general rule: valueAfter == totalRemaining (reference) vs valueAfter == 0 (bug)
        assertTrue(valueAfter != 0, "Value should not be zero after getTokens when initial value > totalRemaining");
    }
}
